def seed_body(apps, schema_editor):
    """建部位 + 位。两边都用 `get_or_create`，幂等。"""
    BodyPart = apps.get_model('wealth', 'WealthBodyPart')
    BodyNeed = apps.get_model('wealth', 'WealthBodyNeed')

    for index, (name, note) in enumerate(BODY_PART_SEEDS):
        BodyPart.objects.get_or_create(
            user_id=1, name=name,
            defaults={'note': note, 'sort_order': index},
        )

    parts = {p.name: p for p in BodyPart.objects.filter(user_id=1)}
    for part_name, need_name in BODY_NEED_SEEDS:
        part = parts.get(part_name)
        if part is None:
            # 理论上不会走到（上一段刚建过）；空库/被并发删掉时不崩
            continue
        BodyNeed.objects.get_or_create(
            user_id=1, part=part, name=need_name,
            defaults={'find_status': 'todo', 'wish': ''},
        )


def unseed_body(apps, schema_editor):
    """回滚：删掉 seed 出来的东西 —— **但只删还保持初始状态的那些**。

    ⚠️ 用户动过的位（进度不是 todo / 有满意 / 有关联 / 有备注 / 有 wish）一律保留；
    部位只要还被任何位引用就不删（`part` 是 PROTECT，硬删也会被 DB 拦住）。
    """
    BodyPart = apps.get_model('wealth', 'WealthBodyPart')
    BodyNeed = apps.get_model('wealth', 'WealthBodyNeed')

    seeded_names = [name for _, name in BODY_NEED_SEEDS]
    BodyNeed.objects.filter(
        user_id=1, name__in=seeded_names,
        find_status='todo', satisfaction__isnull=True,
        property__isnull=True, survival_item__isnull=True,
        note='', wish='',
    ).delete()

    seeded_part_names = [name for name, _ in BODY_PART_SEEDS]
    for part in BodyPart.objects.filter(user_id=1, name__in=seeded_part_names):
        if not part.needs.exists():
            part.delete()


